import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_receipt_fields(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint") or os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = config.get("api_key") or os.environ["AZURE_FORM_RECOGNIZER_KEY"]
    client = DocumentAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))
    poller = client.begin_analyze_document("prebuilt-receipt", document=payload)
    analysis = poller.result()
    result = {"merchant": None, "tax": None, "total": None, "items": []}
    if analysis.documents:
        doc = analysis.documents[0]
        fields = doc.fields or {}

        merchant = fields.get("MerchantName")
        if merchant and merchant.value is not None:
            result["merchant"] = merchant.value

        tax = fields.get("TotalTax")
        if tax and tax.value is not None:
            result["tax"] = float(tax.value)

        total = fields.get("Total")
        if total and total.value is not None:
            result["total"] = float(total.value)

        items = fields.get("Items")
        if items and items.value:
            for item in items.value:
                item_fields = item.value or {}
                name = item_fields.get("Description")
                price = item_fields.get("TotalPrice")
                quantity = item_fields.get("Quantity")
                result["items"].append({
                    "name": name.value if name and name.value is not None else None,
                    "price": float(price.value) if price and price.value is not None else None,
                    "quantity": float(quantity.value) if quantity and quantity.value is not None else None,
                })
    return result
